(()=>{const input=document.querySelector('#smart-product-search');if(!input)return;const cards=[...document.querySelectorAll('.smart-product')],count=document.querySelector('#smart-list-count'),empty=document.querySelector('#smart-search-empty');input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();let visible=0;cards.forEach(card=>{card.hidden=!card.dataset.search.includes(query);if(!card.hidden)visible++});count.textContent=visible+' product'+(visible===1?'':'s');empty.hidden=visible!==0})})();
